package dev.veltraph.client.mining.vein;

import dev.veltraph.client.galatea.FigHarvestPickupLedger.*;
import dev.veltraph.client.world.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.mining.vein.VeinPickupCorrelation.*;

class VeinPickupCorrelationTest {
    final Object player=new Object(),owner=new Object(),world=new Object(),connection=new Object();
    final Scope scope=new Scope(owner,player,world,connection,1,new Object(),1);
    final Context context=new Context(scope,"config-r3","pickaxe-full",0,8,1000);
    final AtomicBoolean custody=new AtomicBoolean(true);
    final VeinPickupCorrelation collector=new VeinPickupCorrelation(context,custody::get);
    final UUID uuid=UUID.fromString("00000000-0000-0000-0000-000000000001");
    final BlockPos target=new BlockPos(10,70,10);
    Issued issue(long serial){return new Issued(serial,serial+1,target,"gray-wool",new Object(),context.tool(),0,8,context.configuration(),100,110);}
    Entity entity(UUID id,int count){return new Entity(id,42,new Vec3(10.4,70.2,10.5),4,130,"wool-unit",count,5,140);}
    Taken take(UUID id,int count){return new Taken(id,42,6,player,"wool-unit",count,150);}
    List<Cell> cells(int amount){var result=new ArrayList<Cell>();for(int i=0;i<36;i++)result.add(new Cell(i,i==0?"pickaxe-unit":i==1&&amount>0?"wool-unit":"empty",i==0?1:i==1?amount:0,i==0?"pickaxe-full":i==1&&amount>0?"wool-full-"+amount:"empty-full"));return result;}
    List<Object> full(List<Cell> cells){return cells.stream().map(Cell::canonicalFullIdentity).toList();}
    Inventory inventory(int amount){return new Inventory(7,160,cells(0),cells(amount));}
    void issued(){assertTrue(collector.issued(context,issue(1),110));}
    void chain(){issued();assertTrue(collector.air(context,1,new Air(3,120,true),120));assertTrue(collector.entity(context,entity(uuid,1),140));assertTrue(collector.taken(context,take(uuid,1),150));assertTrue(collector.inventory(context,inventory(1),160));}
    @Test void exactNativeChainAllowsOneShotCas(){chain();var permit=collector.review(context,1,full(cells(0)),full(cells(1)),170).orElseThrow();var cas=new AtomicInteger();assertTrue(collector.commit(context,permit,170,()->{cas.incrementAndGet();return true;}));assertFalse(collector.commit(context,permit,170,()->true));assertEquals(1,cas.get());}
    @Test void predictedAirCannotAuthorize(){issued();assertFalse(collector.air(context,1,new Air(3,120,false),120));assertTrue(collector.entity(context,entity(uuid,1),140));assertTrue(collector.taken(context,take(uuid,1),150));assertFalse(collector.inventory(context,inventory(1),160));assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),170).isEmpty());}
    @Test void foreignRecipientTaintsDrop(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);assertFalse(collector.taken(context,new Taken(uuid,42,6,new Object(),"wool-unit",1,150),150));assertFalse(collector.inventory(context,inventory(1),160));}
    @Test void fullComponentsMustMatchTake(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);assertFalse(collector.taken(context,new Taken(uuid,42,6,player,"wool-with-foreign-component",1,150),150));assertFalse(collector.inventory(context,inventory(1),160));}
    @Test void twoEligibleOriginsDenyEvenWhenOnlyOneHasAir(){issued();assertTrue(collector.issued(context,issue(20),110));collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);collector.taken(context,take(uuid,1),150);assertFalse(collector.inventory(context,inventory(1),160));}
    @Test void unrelatedCellChangeDeniesWholeInventory(){chain();var foreign=new ArrayList<Cell>(cells(1));foreign.set(35,new Cell(35,"diamond-unit",1,"diamond-full"));assertTrue(collector.review(context,1,full(cells(0)),full(foreign),170).isEmpty());}
    @Test void toolWearMustBeProjectedSeparately(){chain();var wear=new ArrayList<Cell>(cells(1));wear.set(0,new Cell(0,"pickaxe-unit-worn",1,"pickaxe-full-worn"));assertTrue(collector.review(context,1,full(cells(0)),full(wear),170).isEmpty());}
    @Test void deliveryIntoToolSlotIsDenied(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);collector.taken(context,take(uuid,1),150);var after=new ArrayList<Cell>(cells(0));after.set(0,new Cell(0,"wool-unit",2,"wool-full-2"));assertFalse(collector.inventory(context,new Inventory(7,160,cells(0),after),160));}
    @Test void inventoryMayBeObservedBeforeAirWithoutInventingReceipt(){issued();collector.entity(context,entity(uuid,1),140);collector.taken(context,take(uuid,1),150);assertFalse(collector.inventory(context,inventory(1),160));assertTrue(collector.air(context,1,new Air(3,155,true),170));assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),180).isPresent());}
    @Test void airAfterInventoryJoinsOnlyAfterActualReceipt(){issued();collector.entity(context,entity(uuid,1),140);collector.taken(context,take(uuid,1),150);collector.inventory(context,inventory(1),160);assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),165).isEmpty());collector.air(context,1,new Air(3,170,true),170);assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),180).isPresent());}
    @Test void missingTakeCannotAuthorize(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);assertFalse(collector.inventory(context,inventory(1),160));}
    @Test void amountMustCloseExactly(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,2),140);collector.taken(context,take(uuid,2),150);assertFalse(collector.inventory(context,inventory(1),160));}
    @Test void duplicateEntityMetadataCannotIncreaseAuthorizedCount(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);assertFalse(collector.entity(context,entity(uuid,2),140));collector.taken(context,take(uuid,1),150);assertFalse(collector.inventory(context,inventory(1),160));}
    @Test void contextRevocationBetweenReviewAndCommitDeniesCas(){chain();var permit=collector.review(context,1,full(cells(0)),full(cells(1)),170).orElseThrow();custody.set(false);var cas=new AtomicInteger();assertFalse(collector.commit(context,permit,180,()->{cas.incrementAndGet();return true;}));assertEquals(0,cas.get());}
    @Test void configurationAbaRequiresProducerRevisionStamp(){chain();var changed=new Context(scope,"config-r5-same-values",context.tool(),0,8,1000);assertTrue(collector.review(changed,1,full(cells(0)),full(cells(1)),170).isEmpty());assertTrue(collector.retired());}
    @Test void foreignWorldOrOwnerCannotConsume(){chain();var foreign=new Context(new Scope(owner,player,new Object(),connection,1,scope.treeIdentity(),1),context.configuration(),context.tool(),0,8,1000);assertTrue(collector.review(foreign,1,full(cells(0)),full(cells(1)),170).isEmpty());}
    @Test void originalDeadlineAndRollbackRetire(){chain();assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),1001).isEmpty());assertTrue(collector.retired());}
    @Test void clockRollbackRetires(){issued();assertFalse(collector.air(context,1,new Air(3,105,true),105));assertTrue(collector.retired());}
    @Test void failedCasRetainsPermitUntilFreshSuccessfulCas(){chain();var permit=collector.review(context,1,full(cells(0)),full(cells(1)),170).orElseThrow();assertFalse(collector.commit(context,permit,170,()->false));assertTrue(collector.commit(context,permit,180,()->true));}
    @Test void newOriginCannotResetReplayHistory(){chain();assertFalse(collector.issued(context,new Issued(20,21,target,"gray-wool",new Object(),context.tool(),0,8,context.configuration(),170,180),180));assertTrue(collector.retired());}
    @Test void capacityIsFiniteAndDeniesOverflow(){for(int i=0;i<MAX_ORIGINS;i++)assertTrue(collector.issued(context,new Issued(1+i*2,2+i*2,target,"gray-wool",new Object(),context.tool(),0,8,context.configuration(),100,110),110));assertFalse(collector.issued(context,issue(200),110));assertTrue(collector.retired());}
    @Test void changedCameraEpochOrSlotDenies(){issued();assertFalse(collector.air(new Context(scope,context.configuration(),context.tool(),0,9,1000),1,new Air(3,120,true),120));assertTrue(collector.retired());}
    @Test void stagedDropTaintRevokesOutstandingPermit(){chain();var permit=collector.review(context,1,full(cells(0)),full(cells(1)),170).orElseThrow();assertFalse(collector.entity(context,entity(uuid,2),180));assertTrue(collector.retired());assertFalse(collector.commit(context,permit,180,()->true));}
    @Test void malformedInventoryCannotPublishPermission(){issued();assertFalse(collector.inventory(context,new Inventory(7,160,cells(0).subList(0,35),cells(1)),160));}
    @Test void inventoryBeforeTakeJoinsOnlyAfterActualTake(){issued();collector.air(context,1,new Air(3,120,true),120);collector.entity(context,entity(uuid,1),140);collector.inventory(context,new Inventory(7,145,cells(0),cells(1)),145);assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),146).isEmpty());collector.taken(context,take(uuid,1),150);assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),160).isPresent());}
    @Test void attributedPendingDeliveryMeansWaitOnly(){issued();collector.entity(context,entity(uuid,1),140);collector.inventory(context,new Inventory(7,145,cells(0),cells(1)),145);assertTrue(collector.pendingExact(context,full(cells(0)),full(cells(1)),146));assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),146).isEmpty());}
    @Test void pendingForeignDeltaIsDenied(){issued();collector.entity(context,entity(uuid,1),140);collector.inventory(context,new Inventory(7,145,cells(0),cells(1)),145);var foreign=new ArrayList<Object>(full(cells(1)));foreign.set(35,"foreign-full");assertFalse(collector.pendingExact(context,full(cells(0)),foreign,146));}
    @Test void identicalItemDataBeforeAndAfterAirKeepsFirstReceiptWithoutDoubleCredit(){issued();assertTrue(collector.entity(context,entity(uuid,1),140));assertTrue(collector.air(context,1,new Air(6,145,true),145));assertTrue(collector.entity(context,new Entity(uuid,42,new Vec3(10.4,70.2,10.5),4,130,"wool-unit",1,7,150),150));assertTrue(collector.taken(context,new Taken(uuid,42,8,player,"wool-unit",1,160),160));assertTrue(collector.inventory(context,new Inventory(9,170,cells(0),cells(1)),170));var permit=collector.review(context,1,full(cells(0)),full(cells(1)),180).orElseThrow();assertTrue(collector.commit(context,permit,180,()->true));assertTrue(collector.review(context,1,full(cells(0)),full(cells(2)),190).isEmpty());}
    @Test void identicalDataWithoutAirStillCannotAuthorize(){issued();collector.entity(context,entity(uuid,1),140);assertTrue(collector.entity(context,new Entity(uuid,42,new Vec3(10.4,70.2,10.5),4,130,"wool-unit",1,7,150),150));collector.taken(context,new Taken(uuid,42,8,player,"wool-unit",1,160),160);collector.inventory(context,new Inventory(9,170,cells(0),cells(1)),170);assertTrue(collector.review(context,1,full(cells(0)),full(cells(1)),180).isEmpty());}
    @Test void repeatedDataCannotChangeComponentsOrCount(){issued();collector.entity(context,entity(uuid,1),140);assertFalse(collector.entity(context,new Entity(uuid,42,new Vec3(10.4,70.2,10.5),4,130,"foreign-unit",1,7,150),150));}
    @Test void repeatedDataCannotReassignNativeEntityOrOrigin(){issued();collector.entity(context,entity(uuid,1),140);assertFalse(collector.entity(context,new Entity(uuid,43,new Vec3(10.4,70.2,10.5),4,130,"wool-unit",1,7,150),150));}
    @Test void repeatedOldDataSerialIsNotNewNativeReceipt(){issued();collector.entity(context,entity(uuid,1),140);assertFalse(collector.entity(context,entity(uuid,1),150));}
    @Test void changedSpawnReceiptCannotReuseUuid(){issued();collector.entity(context,entity(uuid,1),140);assertFalse(collector.entity(context,new Entity(uuid,42,new Vec3(10.4,70.2,10.5),6,145,"wool-unit",1,7,150),150));}
    @Test void repeatedNewerDataSerialCannotReplayTwice(){issued();collector.entity(context,entity(uuid,1),140);var repeat=new Entity(uuid,42,new Vec3(10.4,70.2,10.5),4,130,"wool-unit",1,7,150);assertTrue(collector.entity(context,repeat,150));assertFalse(collector.entity(context,repeat,160));}
}
